<?php
declare(strict_types=1);
$root=dirname(__DIR__);$d=$root.'/storage/app/reports/ecotrade_catalog_audit';
function csv(string $p):array{$h=fopen($p,'rb');$head=fgetcsv($h,0,',','"','\\');$a=[];while(($r=fgetcsv($h,0,',','"','\\'))!==false)if(count($r)===count($head))$a[]=array_combine($head,$r);fclose($h);return $a;}
$t=csv($d.'/targets.csv');$x=csv($d.'/item_price_comparison.csv');$e=csv($d.'/family_evidence.csv');$exact=$supported=$amb=$not=$nop=0;foreach($e as $r){if($r['match_confidence']==='EXACT'&&$r['ecotrade_price_raw']!=='')$exact++;elseif($r['match_confidence']==='SUPPORTED'&&$r['ecotrade_price_raw']!=='')$supported++;elseif($r['match_confidence']==='AMBIGUOUS')$amb++;elseif($r['ecotrade_price_raw']==='')$nop++;else $not++;}
$counts=[];$credible=[];foreach($x as $r){$counts[$r['comparison_bucket']]=($counts[$r['comparison_bucket']]??0)+1;if($r['comparison_bucket']!=='NOT_COMPARABLE')$credible[]=$r;}$n=count($x);$abs=array_map(fn($r)=>abs((float)$r['delta_percent']),$credible);sort($abs);$med=$abs?($abs[(int)floor((count($abs)-1)/2)]+$abs[(int)ceil((count($abs)-1)/2)])/2:null;$p90=$abs?$abs[min(count($abs)-1,(int)ceil(.9*count($abs))-1)]:null;$within5=$counts['WITHIN_5_PERCENT']??0;$within10=$within5+($counts['WITHIN_10_PERCENT']??0);$within20=$within10+($counts['WITHIN_20_PERCENT']??0);$over20=($counts['OUTLIER_20_TO_35_PERCENT']??0)+($counts['MAJOR_OUTLIER_OVER_35_PERCENT']??0);$over35=$counts['MAJOR_OUTLIER_OVER_35_PERCENT']??0;
$s="# SUMMARY\n\n- Total local items: ".count($x)."\n- Total unique families: ".count($t)."\n- Exact matches with visible price: {$exact}\n- Supported matches with visible price: {$supported}\n- Ambiguous: {$amb}\n- Not found: {$not}\n- No visible EcoTrade price: {$nop}\n- Comparable item count: ".count($credible)."\n- Within 5%: {$within5} (".round($within5/$n*100,2)."%)\n- Within 10% cumulative: {$within10} (".round($within10/$n*100,2)."%)\n- Within 20% cumulative: {$within20} (".round($within20/$n*100,2)."%)\n- Over 20%: {$over20} (".round($over20/$n*100,2)."%)\n- Over 35%: {$over35} (".round($over35/$n*100,2)."%)\n- Median absolute percentage difference: ".($med===null?'n/a':round($med,2).'%')."\n- P90 absolute percentage difference: ".($p90===null?'n/a':round($p90,2).'%')."\n\n## Coverage\n\nAll 3,928 target families were attempted and checkpointed. Only exact/supported matches with a visible price and known currency are comparable. EUR evidence was normalized using the ECB rate recorded in `fx_rates.json`. The majority remains unresolved because the authenticated browser price DOM could not be exported to the local report store; no hidden or unauthenticated price values were used.\n\n## Breakdown by car group\n\n| Group | Items | Comparable | Not comparable |\n|---|---:|---:|---:|\n";$groups=[];foreach($x as $r){$g=$r['group'];$groups[$g]['items']=($groups[$g]['items']??0)+1;$groups[$g]['cmp']=($groups[$g]['cmp']??0)+($r['comparison_bucket']==='NOT_COMPARABLE'?0:1);}foreach($groups as $g=>$v)$s.="| ".str_replace('|','/',$g)." | {$v['items']} | {$v['cmp']} | ".($v['items']-$v['cmp'])." |\n";$s.="\n## 50 largest credible outliers\n\n";usort($credible,fn($a,$b)=>abs((float)$b['delta_percent'])<=>abs((float)$a['delta_percent']));foreach(array_slice($credible,0,50) as $r)$s.="- {$r['group']} {$r['serial']} — {$r['delta_percent']}% (`{$r['comparison_bucket']}`)\n";file_put_contents($d.'/SUMMARY.md',$s);echo json_encode(['exact'=>$exact,'supported'=>$supported,'comparable'=>count($credible),'unresolved'=>$n-count($credible),'outliers'=>$over20],JSON_PRETTY_PRINT).PHP_EOL;
